mapper.select:
SELECT t_system_role.id, t_system_role.role_name AS roleName, t_system_role.remark, t_system_role.`status`, CASE t_system_role.`status` WHEN 0 THEN '正常' WHEN 1 THEN '禁用' ELSE '' END AS statusName, t_system_role.gmt_create AS gmtCreate, t_system_role.gmt_modified AS gmtModified, t_system_role.org_no AS orgNo, t_system_role.org_name AS orgName FROM t_system_role WHERE t_system_role.is_deleted = #{param.deleted}
AND t_system_role.role_name LIKE CONCAT('%', #{param.roleName}, '%')
AND t_system_role.id = #{param.id}
AND t_system_role.status = #{param.status}
AND t_system_role.create_by = #{param.createBy}
ORDER BY t_system_role.gmt_modified DESC
